// Conformance demo page for shadcn/ui. The `@/components/ui/*` files are NOT in this
// repository: they are generated by the shadcn CLI into a directory outside it and mapped
// with build.js --src (see ../README.md). Styling is shadcn's own Tailwind theme, compiled
// to build/app.css. shadcn's Table is presentational (no sort or filter), so those table
// checks are not applicable; no static alert is declared.
import { createRoot } from 'react-dom/client';
import { toast } from 'sonner';
import { Button } from '@/components/ui/button';
import { Toggle } from '@/components/ui/toggle';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Dialog, DialogClose, DialogContent, DialogDescription, DialogFooter, DialogHeader, DialogTitle, DialogTrigger } from '@/components/ui/dialog';
import { DropdownMenu, DropdownMenuContent, DropdownMenuItem, DropdownMenuTrigger } from '@/components/ui/dropdown-menu';
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui/tabs';
import { Tooltip, TooltipContent, TooltipProvider, TooltipTrigger } from '@/components/ui/tooltip';
import { Popover, PopoverContent, PopoverTrigger } from '@/components/ui/popover';
import { Accordion, AccordionContent, AccordionItem, AccordionTrigger } from '@/components/ui/accordion';
import { Toaster } from '@/components/ui/sonner';
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from '@/components/ui/table';
import { Pagination, PaginationContent, PaginationItem, PaginationLink, PaginationNext, PaginationPrevious } from '@/components/ui/pagination';
import { NavigationMenu, NavigationMenuContent, NavigationMenuItem, NavigationMenuLink, NavigationMenuList, NavigationMenuTrigger } from '@/components/ui/navigation-menu';

const people = [['Ada', 'Engineer'], ['Grace', 'Admiral'], ['Margaret', 'Director'], ['Barbara', 'Professor'], ['Karen', 'Researcher']];

function App() {
  return (
    <TooltipProvider>
      <header className="p-4">
        <NavigationMenu id="sh-nav" aria-label="Main">
          <NavigationMenuList>
            <NavigationMenuItem><NavigationMenuLink href="#home">Home</NavigationMenuLink></NavigationMenuItem>
            <NavigationMenuItem><NavigationMenuLink href="#docs" active>Docs</NavigationMenuLink></NavigationMenuItem>
            <NavigationMenuItem>
              <NavigationMenuTrigger id="sh-nav-more">More</NavigationMenuTrigger>
              <NavigationMenuContent>
                <ul className="w-48">
                  <li><NavigationMenuLink href="#blog">Blog</NavigationMenuLink></li>
                  <li><NavigationMenuLink href="#about">About</NavigationMenuLink></li>
                </ul>
              </NavigationMenuContent>
            </NavigationMenuItem>
          </NavigationMenuList>
        </NavigationMenu>
      </header>
      <main id="demo" className="mx-auto max-w-3xl space-y-8 p-4">
        <h1 className="text-2xl font-semibold">shadcn/ui conformance demo</h1>

        <section id="c-button" aria-labelledby="h-button" className="space-x-2">
          <h2 id="h-button" className="text-lg font-medium">Button and Toggle</h2>
          <Button id="sh-save">Save draft</Button>
          <Toggle id="sh-bold" variant="outline">Bold</Toggle>
          <Button id="sh-off" disabled>Publish</Button>
        </section>

        <section id="c-text-field" aria-labelledby="h-text-field">
          <h2 id="h-text-field" className="text-lg font-medium">Text field (Label + Input)</h2>
          <form onSubmit={(e) => e.preventDefault()} className="space-y-2">
            <Label htmlFor="sh-email">Email address</Label>
            <Input id="sh-email" name="email" type="email" required />
            <Button type="submit" id="sh-email-submit">Save email</Button>
          </form>
        </section>

        <section id="c-select" aria-labelledby="h-select">
          <h2 id="h-select" className="text-lg font-medium">Select</h2>
          <Label id="sh-fruit-label" htmlFor="sh-select">Fruit</Label>
          <Select defaultValue="apple">
            <SelectTrigger id="sh-select"><SelectValue /></SelectTrigger>
            <SelectContent>
              <SelectItem value="apple">Apple</SelectItem>
              <SelectItem value="banana">Banana</SelectItem>
              <SelectItem value="cherry">Cherry</SelectItem>
            </SelectContent>
          </Select>
        </section>

        <section id="c-dialog" aria-labelledby="h-dialog">
          <h2 id="h-dialog" className="text-lg font-medium">Dialog</h2>
          <Dialog>
            <DialogTrigger asChild><Button id="sh-dialog-open" variant="outline">Rename project</Button></DialogTrigger>
            <DialogContent>
              <DialogHeader>
                <DialogTitle>Rename project</DialogTitle>
                <DialogDescription>Pick a name your team will recognise.</DialogDescription>
              </DialogHeader>
              <Label htmlFor="sh-name">Project name</Label>
              <Input id="sh-name" defaultValue="Atlas" />
              <DialogFooter>
                <DialogClose asChild><Button variant="outline">Cancel</Button></DialogClose>
                <DialogClose asChild><Button>Save</Button></DialogClose>
              </DialogFooter>
            </DialogContent>
          </Dialog>
        </section>

        <section id="c-menu" aria-labelledby="h-menu">
          <h2 id="h-menu" className="text-lg font-medium">Dropdown menu</h2>
          <DropdownMenu>
            <DropdownMenuTrigger asChild><Button id="sh-menu-btn" variant="outline">Actions</Button></DropdownMenuTrigger>
            <DropdownMenuContent>
              <DropdownMenuItem>Duplicate</DropdownMenuItem>
              <DropdownMenuItem>Archive</DropdownMenuItem>
              <DropdownMenuItem>Delete</DropdownMenuItem>
            </DropdownMenuContent>
          </DropdownMenu>
        </section>

        <section id="c-tabs" aria-labelledby="h-tabs">
          <h2 id="h-tabs" className="text-lg font-medium">Tabs</h2>
          <Tabs defaultValue="plan">
            <TabsList id="sh-tabs" aria-label="Billing">
              <TabsTrigger value="plan">Plan</TabsTrigger>
              <TabsTrigger value="invoices">Invoices</TabsTrigger>
              <TabsTrigger value="payment">Payment</TabsTrigger>
            </TabsList>
            <TabsContent value="plan"><p>You are on the monthly plan.</p></TabsContent>
            <TabsContent value="invoices"><p>No invoices yet.</p></TabsContent>
            <TabsContent value="payment"><p>Card ending 4242.</p></TabsContent>
          </Tabs>
        </section>

        <section id="c-tooltip" aria-labelledby="h-tooltip" className="space-x-2">
          <h2 id="h-tooltip" className="text-lg font-medium">Tooltip and popover</h2>
          <Tooltip>
            <TooltipTrigger asChild><Button id="sh-tip-btn" variant="outline">Copy link</Button></TooltipTrigger>
            <TooltipContent>Copies the share link</TooltipContent>
          </Tooltip>
          <Popover>
            <PopoverTrigger asChild><Button id="sh-pop-btn" variant="outline">Filters</Button></PopoverTrigger>
            <PopoverContent aria-label="Filters">
              <label className="flex items-center gap-2"><input type="checkbox" /> Only open items</label>
            </PopoverContent>
          </Popover>
        </section>

        <section id="c-accordion" aria-labelledby="h-accordion">
          <h2 id="h-accordion" className="text-lg font-medium">Accordion</h2>
          <Accordion type="multiple" defaultValue={['shipping']}>
            <AccordionItem value="shipping"><AccordionTrigger className="acc">Shipping</AccordionTrigger><AccordionContent>Ships in two days.</AccordionContent></AccordionItem>
            <AccordionItem value="returns"><AccordionTrigger className="acc">Returns</AccordionTrigger><AccordionContent>Thirty days, no questions.</AccordionContent></AccordionItem>
            <AccordionItem value="warranty"><AccordionTrigger className="acc">Warranty</AccordionTrigger><AccordionContent>One year.</AccordionContent></AccordionItem>
          </Accordion>
        </section>

        <section id="c-toast" aria-labelledby="h-toast">
          <h2 id="h-toast" className="text-lg font-medium">Toast (Sonner)</h2>
          <Button id="sh-toast-btn" variant="outline" onClick={() => toast('Settings saved.', { duration: 10000 })}>Save settings</Button>
          <Toaster closeButton />
        </section>

        <section id="c-table" aria-labelledby="h-table">
          <h2 id="h-table" className="text-lg font-medium">Table</h2>
          <Table id="sh-table">
            <TableHeader><TableRow><TableHead>Name</TableHead><TableHead>Role</TableHead></TableRow></TableHeader>
            <TableBody>{people.map(([n, r]) => <TableRow key={n}><TableCell>{n}</TableCell><TableCell>{r}</TableCell></TableRow>)}</TableBody>
          </Table>
        </section>

        <section id="c-pagination" aria-labelledby="h-pagination">
          <h2 id="h-pagination" className="text-lg font-medium">Pagination</h2>
          <Pagination id="sh-pagination">
            <PaginationContent>
              <PaginationItem><PaginationPrevious href="#page-1" /></PaginationItem>
              <PaginationItem><PaginationLink href="#page-1">1</PaginationLink></PaginationItem>
              <PaginationItem><PaginationLink href="#page-2" isActive>2</PaginationLink></PaginationItem>
              <PaginationItem><PaginationLink href="#page-3">3</PaginationLink></PaginationItem>
              <PaginationItem><PaginationNext href="#page-3" /></PaginationItem>
            </PaginationContent>
          </Pagination>
        </section>
      </main>
    </TooltipProvider>
  );
}

createRoot(document.getElementById('root')).render(<App />);
